from __future__ import annotations

def calculate_squares(a, b):
    return (a ** 2, b ** 2)

def calculate_sum_of_squares(a, b, c, d):
    sum1 = calculate_squares(a, b)
    sum2 = calculate_squares(c, d)
    n = sum1 * sum2
    return n

def find_possible_pairs(n):
    pairs = []
    for e in range(int(n ** 0.5) + 1):
        f = n - e ** 2
        if f >= 0 and int(f ** 0.5) ** 2 == f:
            pairs.append([min(e, f), max(e, f)])
    return sorted(pairs)

def prod2sum(a, b, c, d):
    sum1 = calculate_sum_of_squares(a, b)
    sum2 = calculate_sum_of_squares(c, d)
    n = sum1 * sum2
    pairs = find_possible_pairs(n)
    result = []
    for e, f in pairs:
        if e <= f:
            result.append([e, f])
    result.sort()
    return result

