    sum_cd = calculate_squares(c, d)
    n = sum_ab * sum_cd
    products = calculate_products(a, b, c, d)
    possible_sums = find_possible_sums(products)
    solutions = []
    for e in possible_sums:
        f = n - e
        if f >= 0 and calculate_squares(e, f) == n:
            solutions.append([min(e, f), max(e, f)])
    return sorted(solutions)

