from __future__ import annotations

def find_corners(lines):
    corners = []
    for y, line in enumerate(lines):
        for x, char in enumerate(line):
            if char == '+':
                corners.append((x, y))
    return corners

def is_square(lines, top_left, bottom_right):
    x1, y1 = top_left
    x2, y2 = bottom_right
    side_length = x2 - x1 + 1
    for i in range(y1, y2 + 1):
        if lines[i][x1] != '+' or lines[i][x2] != '+':
            return False
    for j in range(x1, x2 + 1):
        if lines[y1][j] != '+' or lines[y2][j] != '+':
            return False
    for i in range(y1 + 1, y2):
        for j in range(x1 + 1, x2):
            if lines[i][j] != ' ':
                return False
    return True

def count_squares(lines):
    corners = find_corners(lines)
    square_count = 0
    for i in range(len(corners)):
        for j in range(i + 1, len(corners)):
            for k in range(j + 1, len(corners)):
                for l in range(k + 1, len(corners)):
                    top_left = min(corners[i], corners[j], corners[k], corners[l])
                    bottom_right = max(corners[i], corners[j], corners[k], corners[l])
                    if is_square(lines, top_left, bottom_right):
                        square_count += 1
    return square_count

