    """
    Convert a number to its corresponding letter.
    """
    if is_valid_number(number):
        return chr(number + 64)
    else:
        raise ValueError('Number is not within the valid range for BINGO.')

def contains_all_letters(array):
    required_letters = set('BINGO')
    letters_in_array = set((map_number_to_letter(number) for number in array if is_valid_number(number)))
    return 'WIN' if required_letters.issubset(letters_in_array) else 'LOSE'

def bingo(array):
    if contains_all_letters(array):
        return 'WIN'
    else:
        return 'LOSE'

