def format_string_pair(pair):
    if len(pair) == 2:
        if len(pair[0]) > 1:
            return f'--{pair[0]} {pair[1]}'
        else:
            return f'-{pair[0]} {pair[1]}'
    return pair[0]

def format_string_list(lst):
    formatted_list = []
    for item in lst:
        if isinstance(item, list):
            formatted_list.append(format_string_pair(item))
        else:
            formatted_list.append(item)
    return ' '.join(formatted_list)

def format_single_string(s):
    if isinstance(s, list):
        if len(s) == 2:
            prefix = '--' if len(s[0]) > 1 else '-'
            return f'{prefix}{s[0]} {s[1]}'
        else:
            return ' '.join(s)
    return s

def args_to_string(args):
    result = []
    for arg in args:
        if isinstance(arg, list):
            if len(arg) == 2:
                prefix = '--' if len(arg[0]) > 1 else '-'
                result.append(f'{prefix}{arg[0]} {arg[1]}')
            else:
                result.append(format_string_list(arg))
        else:
            result.append(format_single_string(arg))
    return ' '.join(result)

