def count_hits(round_data, double_points):
    pete_hits = 0
    phil_hits = 0
    for hits in round_data.values():
        pete_hits += hits.count('X') * (2 if double_points else 1)
        phil_hits += hits.count('X') * (2 if double_points else 1)
    return (pete_hits, phil_hits)

def calculate_total_hits(rounds):
    pete_total = 0
    phil_total = 0
    for round_data, double_points in rounds:
        pete_hits, phil_hits = count_hits(round_data, double_points)
        pete_total += pete_hits
        phil_total += phil_hits
    return (pete_total, phil_total)

def determine_winner(pete_total, phil_total):
    if pete_total > phil_total:
        return 'Pete Wins!'
    elif phil_total > pete_total:
        return 'Phil Wins!'
    else:
        return 'Draw!'

def shoot(results):
    pete_total, phil_total = calculate_total_hits(results)
    return determine_winner(pete_total, phil_total)

