def next_element(n):
    if n < 10:
        return n + n
    else:
        digits = [int(d) for d in str(n) if d != '0']
        product = 1
        for d in digits:
            product *= d
        return n + product

def is_converged(n):
    base_series = {1, 2, 4, 8, 16, 22, 26, 38, 62, 74, 102, 104, 108, 116, 122}
    return n in base_series

