def find_cat_position(x):
    return x.find('C')

def find_mouse_position(x):
    return x.find('m')

def find_dog_position(x):
    return x.find('D')

def cat_mouse(x, j):
    cat_pos = find_cat_position(x)
    mouse_pos = find_mouse_position(x)
    dog_pos = find_dog_position(x)
    if cat_pos == -1 or mouse_pos == -1 or dog_pos == -1:
        return 'boring without all three'
    if abs(mouse_pos - cat_pos) <= j and (mouse_pos < cat_pos or dog_pos < cat_pos):
        return 'Caught!'
    elif abs(mouse_pos - cat_pos) > j:
        return 'Escaped!'
    else:
        return 'Protected!'

